import {useCatalogWithoutPacks} from './audio-catalog-fixture.js';
import {test,expect} from '@playwright/test';
import {freshState} from '../../src/engine.js';import {freshSentence} from '../../src/sentence-state.js';import {freshKoreanProgress} from '../../src/korean-state.js';
import {prepareContent,caseTasks} from '../../src/practice-content.js';
for(const direction of ['ko-ja','ja-ko'])for(const width of [320,390])test(`2-1 review all stages audio retry resume completion ${direction} ${width}`,async({page})=>{
 const kind=direction==='ko-ja'?'sentence':'korean',id=kind==='sentence'?'3':'3-1',key=`${direction}:${kind}:${id}`;
 const s={...freshState(),onboarded:true,courseDirection:direction,onboardingLevel:2,koreanGuideSeenVersion:1,settings:{sound:false,motion:'off',textScale:1.2,audioRate:1},sentenceActive:3,sentenceLessons:{3:{...freshSentence(),started:true,index:5,phase:'speak',learned:[0,1,2,3,4]}},korean:{version:4,active:'3-1',lessons:{'3-1':{...freshKoreanProgress('3-1'),started:true,index:5,phase:'speak',caseSeen:true}}}};
 await prepareContent(kind);const tasks=caseTasks(s,kind);
 await page.setViewportSize({width,height:width===320?640:844});
 await page.addInitScript(s=>{if(!localStorage.getItem('seodang.web-prototype.v1'))localStorage.setItem('seodang.web-prototype.v1',JSON.stringify(s));localStorage.setItem('seodang.analytics.v1',JSON.stringify({consent:false,queue:[]}));window.played=[];window.Audio=class{constructor(src){this.src=src;}play(){window.played.push(this.src);queueMicrotask(()=>this.onended?.());return Promise.resolve();}pause(){}};},s);
 await useCatalogWithoutPacks(page);
 const enter=async()=>{await page.locator(`.map-choice[data-action="${kind}"][data-id="${id}"]`).click();await page.locator('[data-choice="resume"]').click();};
 await page.goto('/playable.html');await enter();await page.locator('[data-speaking-skip]').click();await expect(page.locator('.introduction-review')).toBeVisible();
 const state=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('seodang.web-prototype.v1')));
 const layout=async()=>{expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1)).toBe(true);for(const row of await page.locator('.introduction-review .audio-text-row:visible').all()){const b=await row.evaluate(el=>({text:el.querySelector('p,h2').getBoundingClientRect(),button:el.querySelector('button').getBoundingClientRect()}));expect(b.button.left).toBeGreaterThanOrEqual(b.text.right-1);expect(b.button.width).toBeGreaterThanOrEqual(44);}const pair=page.locator('.introduction-review .button-pair');if(await pair.count()){const y=await pair.locator('button').evaluateAll(xs=>xs.map(x=>x.getBoundingClientRect().top));expect(Math.abs(y[0]-y[1])).toBeLessThan(2);}};
 for(let i=0;i<21;i++){
  const task=tasks[i],confirm=page.locator('[data-review-confirm]');await expect(page.locator('.case-task-count')).toHaveCount(0);expect((await state()).practices[key].index).toBe(i);await expect(page.locator('.review-result')).toBeHidden();await layout();
  if(i===0||i===3||i===9||i===15){await page.screenshot({path:`output/review21-${direction}-${width}-${i}-${test.info().project.name}.png`,fullPage:true});}
  if(task.type==='word'){const cards=page.locator('.review-word-grid>button');await expect(cards).toHaveCount(4);const rects=await cards.evaluateAll(xs=>xs.map(x=>{const r=x.getBoundingClientRect();return {x:r.x,y:r.y,w:r.width};}));expect(rects[0].y).toBe(rects[1].y);expect(rects[2].y).toBe(rects[3].y);expect(rects[2].y).toBeGreaterThan(rects[0].y);expect(rects[0].x).toBe(rects[2].x);expect(await cards.first().innerText()).toBe('');for(const img of await cards.locator('img').all())expect(await img.evaluate(x=>x.complete&&x.naturalWidth>0)).toBe(true);const before=await page.evaluate(()=>window.played.length);await page.locator(`[data-review-choice="${task.answer}"]`).click();await expect.poll(()=>page.evaluate(()=>window.played.length)).toBeGreaterThan(before);await expect(page.locator('.review-build-meaning')).toHaveText(task.unit.text);}
  if(task.type==='listen'){
   await expect(page.locator('[data-review-transcript] p')).toBeHidden();await page.locator(`[data-review-choice="${task.answer}"]`).click();await expect(confirm).toBeDisabled();
   const before=await page.evaluate(()=>window.played.length);await page.locator('.review-listen [data-review-audio]').click();await expect.poll(()=>page.evaluate(()=>window.played.length)).toBeGreaterThan(before);await expect(confirm).toBeEnabled();
  }
  if(task.type==='order'){
   const count=task.answerLength??task.tokens.length;
   await page.locator('[data-review-token="0"]').click();await page.locator('[data-review-token="1"]').click();await page.locator('[data-review-remove="0"]').click();await expect(page.locator('[data-review-remove]')).toHaveCount(1);await expect(page.locator('[data-review-remove="1"]')).toBeVisible();await expect(page.locator('[data-review-token="0"]')).toBeEnabled();await expect(confirm).toBeDisabled();await page.locator('[data-review-remove="1"]').click();

   for(let n=count-1;n>=0;n--)await page.locator(`[data-review-token="${n}"]`).click();await confirm.click();await expect(page.locator('.review-result')).toBeHidden();expect((await state()).practices[key].index).toBe(i);for(let n=0;n<count;n++)await page.locator('[data-review-undo]').click();for(let n=0;n<count;n++)await page.locator(`[data-review-token="${n}"]`).click();
  }else{await page.locator(`[data-review-choice="${(task.answer+1)%3}"]`).click();await confirm.click();await expect(page.locator('.practice-feedback')).not.toBeEmpty();await expect(page.locator('.review-result')).toBeHidden();await page.locator(`[data-review-choice="${task.answer}"]`).click();}
  await confirm.click();await expect(page.locator('.review-result')).toBeVisible();await expect(page.locator('.review-result .audio-text-row p')).toHaveText(task.unit.text);if(task.type==='order')for(const chip of await page.locator('[data-review-remove]').all())await expect(chip).toBeDisabled();await layout();
  if(i===10){await page.screenshot({path:`output/review21-result-${direction}-${width}-${test.info().project.name}.png`,fullPage:true});}
  if(i===7){await page.reload();await enter();await expect(page.locator('.case-task-count')).toHaveCount(0);await expect(page.locator('.review-result')).toBeHidden();await page.locator('[data-review-transcript] summary').click();await page.locator(`[data-review-choice="${task.answer}"]`).click();await confirm.click();}
  await confirm.click();
 }
 await expect(page.locator('.practice-complete')).toBeVisible();await expect(page.locator('.practice-fireworks svg')).toBeVisible();expect((await state()).practices?.[key]).toBeUndefined();expect(kind==='sentence'?(await state()).sentenceLessons[3].completed:(await state()).korean.lessons['3-1'].completed).toBe(true);
});
for(const direction of ['ko-ja','ja-ko'])test(`2-1 failed listening can retry or use the transcript ${direction}`,async({page})=>{
 await page.route('**/review-fixture',r=>r.fulfill({contentType:'text/html',body:'<!doctype html><html><body></body></html>'}));await page.goto('/review-fixture');await page.evaluate(async direction=>{
  const {freshState}=await import('/src/engine.js'),{prepareContent,caseTasks}=await import('/src/practice-content.js'),{renderIntroductionReview,mountIntroductionReview}=await import('/src/introduction-review.js');
  const kind=direction==='ko-ja'?'sentence':'korean';const s={...freshState(),courseDirection:direction,onboardingLevel:2,sentenceActive:3,korean:{active:'3-1'}};await prepareContent(kind);const task=caseTasks(s,kind)[3],p={index:3,count:21};window.fixtureTask=task;window.advanced=0;window.failAudio=true;
  const root=document.createElement('div');document.body.replaceChildren(root);root.innerHTML=renderIntroductionReview(s,task,p,()=> '');
  mountIntroductionReview(root,s,task,p,{stop(){},play:async(entry,error)=>{if(window.failAudio)error('failed');},advance:()=>window.advanced++});
 },direction);
 const answer=await page.evaluate(()=>window.fixtureTask.answer);await page.locator(`[data-review-choice="${answer}"]`).click();await page.locator('.review-listen [data-review-audio]').click();await expect(page.locator('.practice-feedback')).not.toBeEmpty();await expect(page.locator('[data-review-confirm]')).toBeDisabled();
 await page.locator('[data-review-transcript] summary').click();await expect(page.locator('[data-review-confirm]')).toBeEnabled();await page.locator('[data-review-confirm]').click();await expect(page.locator('.review-result')).toBeVisible();expect(await page.evaluate(()=>window.advanced)).toBe(0);await page.locator('[data-review-confirm]').click();expect(await page.evaluate(()=>window.advanced)).toBe(1);
});
for(const direction of ['ko-ja','ja-ko'])test(`2-1 word taps play only the selected word ${direction}`,async({page})=>{
 await page.route('**/word-review-fixture',r=>r.fulfill({contentType:'text/html',body:'<body></body>'}));await page.goto('/word-review-fixture');
 await page.evaluate(async direction=>{const {freshState}=await import('/src/engine.js'),{introductionWordReview}=await import('/src/introduction-word-content.js'),{renderIntroductionReview,mountIntroductionReview}=await import('/src/introduction-review.js');const s={...freshState(),courseDirection:direction,settings:{sound:false}},task=introductionWordReview(direction==='ja-ko')[0];window.wordTask=task;window.wordPlayed=[];document.body.innerHTML=renderIntroductionReview(s,task,{index:0,count:21},()=> '');mountIntroductionReview(document.body,s,task,{index:0,count:21},{play:async entry=>window.wordPlayed.push(entry),stop(){},advance(){}});},direction);
 const task=await page.evaluate(()=>window.wordTask);for(let i=0;i<task.options.length;i++){await page.locator(`[data-review-choice="${i}"]`).click();await expect.poll(()=>page.evaluate(()=>window.wordPlayed.length)).toBe(i+1);expect(await page.evaluate(()=>window.wordPlayed.at(-1).text)).toBe(task.options[i]);}
 await page.locator(`[data-review-choice="${task.answer}"]`).click();await page.locator('[data-review-confirm]').click();await expect(page.locator('.review-correct-mark')).toBeVisible();await page.locator('.review-result [data-review-audio]').click();expect(await page.evaluate(()=>window.wordPlayed.at(-1).text)).toBe(task.unit.text);
});
test('late picture audio completion cannot erase wrong-answer feedback',async({page})=>{
 await page.route('**/word-audio-race',r=>r.fulfill({contentType:'text/html',body:'<body></body>'}));await page.goto('/word-audio-race');await page.evaluate(async()=>{const {freshState}=await import('/src/engine.js'),{introductionWordReview}=await import('/src/introduction-word-content.js'),{renderIntroductionReview,mountIntroductionReview}=await import('/src/introduction-review.js');const s={...freshState(),settings:{sound:false}},t=introductionWordReview(false,true)[0];document.body.innerHTML=renderIntroductionReview(s,t,{index:0,count:12},()=> '');mountIntroductionReview(document.body,s,t,{index:0,count:12},{play:()=>new Promise(resolve=>window.finishWordAudio=resolve),stop(){},advance(){}});});
 await page.locator('[data-review-choice="0"]').click();await page.locator('[data-review-confirm]').click();await expect(page.locator('.practice-feedback')).toHaveText('다시 생각해 보세요.');await page.evaluate(()=>window.finishWordAudio());await expect(page.locator('.practice-feedback')).toHaveText('다시 생각해 보세요.');await expect(page.locator('.review-result')).toBeHidden();
});
